// ================= Infinite Realms v0.4: progression, disciplines, gear, crafting & economy =================

const irV04ServicesBase=irServices;
irServices=function(kind){const base=irV04ServicesBase(kind)||[];const extra=kind==='hamlet'?['hunter']:kind==='village'?['smithy','hunter']:kind==='remote'?['hunter']:kind==='town'?['smithy','alchemist','hunter']:kind==='city'?['smithy','alchemist','hunter']:[];return [...new Set([...base,...extra])];};
const irV04ServiceNamesBase=irServiceNames;
irServiceNames=function(ids){const names=irV04ServiceNamesBase(ids);const added={smithy:'Blacksmith / forge',alchemist:'Alchemist',hunter:'Hunters & tanners',forge:'Forge',workshop:'Workshop',alchemy:'Alchemy lab'};return (ids||[]).map(id=>added[id]||names[id]||id)};
