for(const [id,d] of Object.entries(IR_V04_ITEM_DATA)){if(ITEMS[id]){ITEMS[id].baseValue=d.value;ITEMS[id].category=d.category;ITEMS[id].shop=d.shop;ITEMS[id].durability=IR_V04_ITEM_DATA[id].durability||100;}}
Object.assign(IR_WEAPON_DATA,{spear:{damage:8,magic:0},wooden_spear:{damage:4,magic:0},bow:{damage:6,magic:0},iron_sword:{damage:9,magic:0}});

function ir04ItemWeight(id){return Number(IR_V04_ITEM_WEIGHT[id]??1)}
function ir04CarryWeight(c=state?.character){if(!c)return 0;return Math.round(Object.entries(c.inventory||{}).reduce((n,[id,count])=>n+ir04ItemWeight(id)*Math.max(0,Number(count)||0),0)*10)/10}
function ir04CarryCapacity(c=state?.character){if(!c)return 0;const base=26+Math.max(0,Number(c.attrs?.Strength)||10)*1.35;return Math.round(base+(c.race==='dwarf'?10:c.race==='orc'?6:c.race==='goblin'?2:c.race==='slimefolk'?5:0))}
function ir04CanCarry(id,qty=1,creditWeight=0){return ir04CarryWeight()-creditWeight+ir04ItemWeight(id)*qty<=ir04CarryCapacity()+.001}
function ir04HasTalent(id){return !!state?.character?.racialTalents?.includes(id)}
function ir04EnsureState(s=state){if(!s?.character)return s;const c=s.character;c.skills=c.skills&&typeof c.skills==='object'?c.skills:{};for(const k of Object.keys(SKILLS))if(!c.skills[k]||typeof c.skills[k]!=='object')c.skills[k]={level:1,xp:0};else{c.skills[k].level=clamp(Math.floor(Number(c.skills[k].level)||1),1,100);c.skills[k].xp=clamp(Math.floor(Number(c.skills[k].xp)||0),0,99)}c.progression=c.progression&&typeof c.progression==='object'?c.progression:{level:1,xp:0,next:120,attributePoints:0,talentPoints:0,totalXp:0};c.progression.level=clamp(Math.floor(Number(c.progression.level)||1),1,100);c.progression.xp=Math.max(0,Number(c.progression.xp)||0);c.progression.next=Math.max(120,Number(c.progression.next)||120);c.progression.attributePoints=Math.max(0,Math.floor(Number(c.progression.attributePoints)||0));c.progression.talentPoints=Math.max(0,Math.floor(Number(c.progression.talentPoints)||0));c.progression.totalXp=Math.max(0,Math.floor(Number(c.progression.totalXp)||0));c.racialTalents=Array.isArray(c.racialTalents)?[...new Set(c.racialTalents.filter(x=>(IR_V04_RACIAL_TALENTS[c.race]||[]).some(t=>t.id===x)))]:[];c.trainingFocus=IR_V04_DISCIPLINES.includes(c.trainingFocus)?c.trainingFocus:({human:'Swordsmanship',dwarf:'Smithing',elf:'Elemental Magic',beastkin:'Tracking',orc:'Swordsmanship',goblin:'Stealth',demonkin:'Elemental Magic',slimefolk:'Alchemy'}[c.race]||'Swordsmanship');c.trainingHistory=Array.isArray(c.trainingHistory)?c.trainingHistory.slice(-100):[];c.itemCondition=c.itemCondition&&typeof c.itemCondition==='object'?c.itemCondition:{};c.itemQuality=c.itemQuality&&typeof c.itemQuality==='object'?c.itemQuality:{};for(const id of Object.keys(c.inventory||{})){if(IR_V04_ITEM_DATA[id]&&c.itemCondition[id]===undefined)c.itemCondition[id]=100}c.professionStats=c.professionStats&&typeof c.professionStats==='object'?c.professionStats:{gathered:0,crafted:0,itemsSold:0,coinsEarned:0,repairs:0};c.professionStats.gathered=Math.max(0,Number(c.professionStats.gathered)||0);c.professionStats.crafted=Math.max(0,Number(c.professionStats.crafted)||0);c.professionStats.itemsSold=Math.max(0,Number(c.professionStats.itemsSold)||0);c.professionStats.coinsEarned=Math.max(0,Number(c.professionStats.coinsEarned)||0);c.professionStats.repairs=Math.max(0,Number(c.professionStats.repairs)||0);s.world.economy=s.world.economy&&typeof s.world.economy==='object'?s.world.economy:{markets:{}};s.world.economy.markets=s.world.economy.markets&&typeof s.world.economy.markets==='object'?s.world.economy.markets:{};s.version=4;return s}
function ir04AwardXP(amount,reason='Progress'){const c=state?.character;if(!c)return;ir04EnsureState();const p=c.progression;const value=Math.max(0,Math.floor(Number(amount)||0));if(!value)return; p.xp+=value;p.totalXp+=value;let levels=0;while(p.xp>=p.next&&p.level<100){p.xp-=p.next;p.level++;p.attributePoints+=2;if(p.level%2===0)p.talentPoints++;p.next=Math.round(120+(p.level-1)*42);levels++;addFeed('⬆️',`Character level ${p.level}`,`Your wider experience in ${reason.toLowerCase()} has helped you grow. You gained 2 attribute points${p.level%2===0?' and 1 racial talent point':''}.`,'milestone')}if(levels)toast(`Character level increased to ${p.level}.`)}
function ir04Needs(s){return Object.entries(s||{}).every(([id,n])=>(state.character.inventory[id]||0)>=n)}
function ir04Consume(needs){for(const [id,n] of Object.entries(needs||{})){state.character.inventory[id]-=n;if(state.character.inventory[id]<=0)delete state.character.inventory[id]}}
function ir04MarketState(siteId=site()?.id){const w=state?.world,c=state?.character;if(!w||!c||!siteId)return null;ir04EnsureState();let m=w.economy.markets[siteId];if(!m){const s=irSiteById(siteId)||site();const rng=irRng(`${w.seed}|economy|${siteId}|v04`);const stock={};for(const [id,d] of Object.entries(IR_V04_ITEM_DATA))stock[id]=Math.max(0,Math.floor((d.stock||0)*(0.6+rng()*0.8)));m={siteId,sales:{},stock,demand:{},baseDemand:{},createdAt:dateLabel(),lastRestockDay:c.daysLived||0,transactions:0};const cat=['food','medicine','wood','ore','metal','herbs','reagent','weapon','armor','leather','fuel'];for(const k of cat)m.demand[k]=Math.round((.82+rng()*.42)*100)/100;if(['mountain'].includes(s?.biomeId)){m.demand.ore=1.3;m.demand.metal=1.12;m.demand.food=1.15}else if(['forest','woodland','swamp'].includes(s?.biomeId)){m.demand.herbs=1.25;m.demand.wood=.85;m.demand.leather=1.15}else if(['coast','river'].includes(s?.biomeId)){m.demand.food=1.22;m.demand.ore=1.12}else if(s?.biomeId==='desert'){m.demand.water=1.4;m.demand.food=1.18}m.baseDemand={...m.demand};w.economy.markets[siteId]=m}if(!m.baseDemand)m.baseDemand={...m.demand};const elapsed=(c.daysLived||0)-(m.lastRestockDay||0);if(elapsed>=30){const periods=Math.min(3,Math.floor(elapsed/30));for(const [id,d] of Object.entries(IR_V04_ITEM_DATA)){m.stock[id]=Math.min((d.stock||0)+2,(m.stock[id]||0)+periods);m.sales[id]=Math.max(0,(m.sales[id]||0)-periods)}for(const key of Object.keys(m.demand||{})){const base=m.baseDemand[key]||1;m.demand[key]=clamp(base+((m.demand[key]||base)-base)*Math.pow(.7,periods),.7,1.5)}m.lastRestockDay=c.daysLived}return m}
function ir04ItemPrice(id,mode='buy',siteId=site()?.id){const d=IR_V04_ITEM_DATA[id];if(!d)return 0;const s=irSiteById(siteId)||site();const m=ir04MarketState(siteId);const c=state.character;const demand=clamp(Number(m?.demand?.[d.category]||1),.7,1.5);const specialty=(d.shop==='smithy'&&s?.services?.some(x=>['forge','workshop','smithy'].includes(x)))?1.12:(d.shop==='alchemist'&&s?.services?.some(x=>['library','alchemy','alchemist','lab'].includes(x)))?1.12:(d.shop==='hunter'&&['forest','snow','woodland','plains'].includes(s?.biomeId))?1.1:1;const trade=clamp(1+(Math.max(0,(c.skills.Trade?.level||1)-1)*.015)+(ir04HasTalent('human_fairtrader')?.08:0),1,1.35);const saturation=1/(1+.05*Math.max(0,Number(m?.sales?.[id]||0)-1)*(ir04HasTalent('goblin_market')?.7:1));const cond=mode==='sell'&&c.itemCondition[id]!==undefined?clamp(.55+(Number(c.itemCondition[id])/100)*.45,.55,1):1;const qualityName=c.itemQuality?.[id]||'Standard';const quality=mode==='sell'?({Poor:.5,Rough:.5,Standard:1,Fine:1.5,Pristine:2.5,Masterwork:3,Legendary:5}[qualityName]||1):1;let value;if(mode==='sell')value=d.value*quality*.58*demand*specialty*trade*saturation*cond;else value=d.value*1.42*demand/specialty/Math.sqrt(trade);return Math.max(1,Math.round(clamp(value,mode==='sell'?d.value*.18:d.value*.72,mode==='sell'?d.value*.88:d.value*1.8)))}
function ir04CanShop(category){const s=site();if(!s)return false;const services=s.services||[];if(category==='general')return services.includes('market')||s.type==='settlement';if(category==='smithy')return s.type==='settlement'&&services.some(x=>['forge','workshop','smithy'].includes(x));if(category==='alchemist')return s.type==='settlement'&&services.some(x=>['library','alchemy','alchemist','lab'].includes(x));if(category==='hunter')return services.some(x=>['hunter','guild','work-board','market'].includes(x))||s.type==='settlement';return false}
function ir04MarketBuy(id){const d=IR_V04_ITEM_DATA[id],c=state.character,s=site();if(!d||!s){toast('That item is unavailable.');return}if(!ir04CanShop(d.shop==='smithy'?'smithy':d.shop==='alchemist'?'alchemist':d.shop==='hunter'?'hunter':'general')){toast(`No ${d.shop} service is available here.`);return}const m=ir04MarketState();if((m.stock[id]||0)<=0){toast('The local shop is out of stock. Prices restock gradually as time passes.');return}if(!ir04CanCarry(id,1)){toast('Your pack is at capacity. Sell, store, or use materials before buying more.');return}const price=ir04ItemPrice(id,'buy');if(c.coin<price){toast(`You need ${coins(price)} for ${ITEMS[id]?.name||id}.`);return}c.coin-=price;c.inventory[id]=(c.inventory[id]||0)+1;c.itemCondition[id]=c.itemCondition[id]===undefined?100:c.itemCondition[id];m.stock[id]--;m.transactions++;m.demand[d.category]=clamp((m.demand[d.category]||1)*1.015,.7,1.5);addFeed('🪙',`Purchased ${ITEMS[id]?.name||id}`,`You paid ${coins(price)} at ${s.name}. The price reflects local demand and shop specialization.`);ir04AwardXP(2,'trading');gainSkill('Trade',3);persist();render();toast(`${ITEMS[id]?.name||id} purchased for ${price} coins.`)}
function ir04MarketSell(id){const c=state.character;if(!(c.inventory[id]>0)){toast('You do not have that item to sell.');return}if(c.equipment?.weapon===id||c.equipment?.armor===id||c.equipment?.offhand===id){toast('Unequip that item before selling it.');return}const d=IR_V04_ITEM_DATA[id];if(!d){toast('This item has no market valuation yet.');return}const m=ir04MarketState();const price=ir04ItemPrice(id,'sell');c.inventory[id]--;if(c.inventory[id]<=0)delete c.inventory[id];c.coin+=price;m.sales[id]=(m.sales[id]||0)+1;m.stock[id]=Math.min((d.stock||0)+6,(m.stock[id]||0)+1);m.transactions++;m.demand[d.category]=clamp((m.demand[d.category]||1)*.985,.7,1.5);c.professionStats.itemsSold++;c.professionStats.coinsEarned+=price;addFeed('🪙',`Sold ${ITEMS[id]?.name||id}`,`You sold one unit for ${coins(price)}. Repeated sales reduce the offer until local demand recovers.`);ir04AwardXP(2,'trading');gainSkill('Trade',4);persist();render();toast(`Sold for ${price} coins.`)}
function ir04Gather(method){const c=state.character,s=site();if(!c||state.combat?.active||state.pendingEvent){toast('Resolve the current encounter or choice before gathering.');return}if(ir04CarryWeight()>=ir04CarryCapacity()){toast('Your pack is at capacity. Sell or use materials before gathering more.');return}const map={mining:{skill:'Mining',energy:11,time:2,label:'Mining'},woodcutting:{skill:'Survival',energy:8,time:1,label:'Woodcutting'},herbalism:{skill:'Herbalism',energy:8,time:1,label:'Herbalism'},fishing:{skill:'Fishing',energy:8,time:1,label:'Fishing'}}[method];if(!map){toast('Unknown gathering activity.');return}if(c.energy<map.energy){toast(`You need ${map.energy} energy for ${map.label.toLowerCase()}.`);return}if(method==='mining'&&!['mountain','desert','snow','cave'].includes(s.biomeId)&&s.risk<28){toast('This area has no safe exposed vein. Try a mountain or rocky high-risk location.');return}c.energy-=map.energy;dayPass(map.time,map.label.toLowerCase());const pool=irBiomeGatheringItems(s,method);const affinityBonus=typeof ir0764GatherChanceBonus==='function'?ir0764GatherChanceBonus(c.race,s,method):0;const chance=clamp(.76+(c.skills[map.skill]?.level||1)*.018-(s.risk||10)*.002+(c.race==='dwarf'&&method==='mining'?.1:0)+affinityBonus,.35,.96);if(Math.random()<chance){let item=pool[Math.floor(Math.random()*pool.length)];let qty=1;if(ir04HasTalent('dwarf_deepminer')&&method==='mining'&&item==='ore')qty++;if(ir04HasTalent('elf_greenhand')&&method==='herbalism'&&item==='herb')qty++;if(ir04HasTalent('goblin_scrap')&&item==='scrap')qty++;if(!ir04CanCarry(item,qty)){gainSkill(map.skill,6);addFeed('🎒',`${map.label}: pack too heavy`,`You found ${ITEMS[item]?.name||item}, but your pack has no room. You keep the experience but leave the material behind.`);toast('Your pack is full; the material was left behind.')}else{c.inventory[item]=(c.inventory[item]||0)+qty;c.professionStats.gathered+=qty;gainSkill(map.skill,18);if(method==='mining')gainSkill('Crafting',5);ir04AwardXP(5+qty*2,map.label);addFeed('⛏️',`${map.label} complete`,`You gathered ${qty} × ${ITEMS[item]?.name||item} in ${s.name}. Skill mastery and local conditions influence the yield.`,'discovery');toast(`Gathered ${ITEMS[item]?.name||item}${qty>1?` ×${qty}`:''}.`)}}else{gainSkill(map.skill,6);addFeed('🧭',`${map.label}: no useful yield`,`You spent time searching ${s.name}, but found nothing worth carrying. The skill practice was not wasted.`);toast('No useful materials this time.')}persist();render()}
function ir04Craft(id){const r=IR_V04_RECIPES[id],c=state.character,s=site();if(!r||!c)return;if(state.combat?.active||state.pendingEvent){toast('Resolve combat or the current event before crafting.');return}const sl=c.skills[r.skill]?.level||1;if(sl<r.level){toast(`${r.name} requires ${r.skill} level ${r.level}.`);return}const services=s.services||[];const stationOK=r.station==='field'||(r.station==='forge'&&services.some(x=>['forge','workshop','smithy'].includes(x)))||(r.station==='alchemy'&&services.some(x=>['library','alchemy','alchemist','lab'].includes(x)));if(!stationOK){toast(r.station==='forge'?'You need a forge or workshop for this recipe.':r.station==='alchemy'?'You need an alchemy-capable library or lab for this recipe.':'You cannot craft that here.');return}if(!ir04Needs(r.needs)){toast(`Missing materials: ${Object.entries(r.needs).filter(([k,n])=>(c.inventory[k]||0)<n).map(([k,n])=>`${n-(c.inventory[k]||0)} ${ITEMS[k]?.name||k}`).join(', ')}.`);return}const inputWeight=Object.entries(r.needs).reduce((sum,[id,n])=>sum+ir04ItemWeight(id)*n,0),outputWeight=Object.entries(r.output).reduce((sum,[id,n])=>sum+ir04ItemWeight(id)*n,0);if(ir04CarryWeight()-inputWeight+outputWeight>ir04CarryCapacity()+.001){toast('Your pack does not have enough room for the crafted result. Sell or store items first.');return}const fee=r.station==='field'?0:6;if(c.coin<fee){toast(`This station needs ${fee} coins in service fees.`);return}c.coin-=fee;ir04Consume(r.needs);c.energy=clamp(c.energy-10,0,c.maxEnergy);dayPass(1,`crafting ${r.name}`);const rank=(c.skills[r.skill]?.level||1)+(c.attrs.Intelligence||10)/8+(ir04HasTalent('dwarf_masterwork')?1.2:0)+(ir04HasTalent('slimefolk_adapt')?1:0);const quality=rank>=5?'Fine':rank>=3?'Standard':'Rough';for(const [out,n] of Object.entries(r.output)){c.inventory[out]=(c.inventory[out]||0)+n;c.itemCondition[out]=100;c.itemQuality[out]=quality}c.professionStats.crafted++;gainSkill(r.skill,24);gainSkill('Crafting',10);ir04AwardXP(12,`crafting ${r.name}`);addFeed(r.icon,`${r.name} completed`,`${quality} result made using ${r.skill}. Materials were consumed and station fees were paid where applicable.`,'milestone');persist();render();toast(`${r.name} crafted (${quality}).`)}
function ir04Repair(slot){const c=state.character,s=site(),id=c.equipment?.[slot];if(!id){toast('There is no equipped item in that slot.');return}if(!['weapon','armor','offhand'].includes(slot))return;const cond=Number(c.itemCondition[id]??100);if(cond>=100){toast('This equipment is already in good condition.');return}if(!(s.services||[]).some(x=>['forge','workshop','smithy'].includes(x))){toast('Travel to a settlement with a blacksmith, forge, or workshop to repair gear.');return}const fee=Math.max(3,Math.ceil((IR_V04_ITEM_DATA[id]?.value||ITEMS[id]?.sell||10)*(100-cond)/180));if(c.coin<fee){toast(`Repair costs ${fee} coins.`);return}c.coin-=fee;c.itemCondition[id]=100;c.professionStats.repairs++;gainSkill('Smithing',10);ir04AwardXP(5,'equipment repair');addFeed('🛠️','Equipment repaired',`${ITEMS[id]?.name||id} was restored to full condition for ${coins(fee)}.`);persist();render();toast('Equipment repaired.');}
function ir04Equip(id){const c=state.character;if(!(c.inventory[id]>0)){toast('That item is not in your inventory.');return}const it=ITEMS[id];if(!it)return;const old=c.equipment||{};if(IR_WEAPON_DATA[id]||it.weaponDamage){if(old.weapon===id)old.weapon=null;else old.weapon=id;}else if(it.armor){const slot=id==='shield'?'offhand':'armor';old[slot]=old[slot]===id?null:id;}else{toast('This item cannot be equipped.');return}c.equipment=old;c.itemCondition[id]=c.itemCondition[id]??100;persist();render();toast(old.weapon===id||old.armor===id||old.offhand===id?`${it.name} equipped.`:`${it.name} loadout changed.`)}
function ir04TrainDiscipline(skill,instructor=false){const c=state.character;if(!IR_V04_DISCIPLINES.includes(skill)||!c.skills[skill]){toast('Choose a supported training discipline.');return}if(state.combat?.active||state.pendingEvent){toast('Finish the current encounter before training.');return}const fee=instructor?8:0;if(instructor&&!((site().services||[]).some(x=>['guild','work-board','forge','library'].includes(x)))){toast('No qualified instructor is available at this location.');return}if(c.coin<fee){toast(`The instructor requires ${fee} coins.`);return}const cost=Math.max(7,(ir04HasTalent('human_quickstudy')?10:13)-(ir04HasTalent('human_adaptable')?2:0));if(c.energy<cost){toast('You are too tired to train. Rest before another session.');return}const oldRecent=(c.trainingHistory||[]).filter(x=>x.skill===skill&&(c.daysLived-x.day)<=7);const mult=oldRecent.length>=3?.35:oldRecent.length===2?.6:1;c.coin-=fee;c.energy-=cost;c.trainingFocus=skill;dayPass(1,`${skill} training`);c.trainingHistory.push({skill,day:c.daysLived,instructor});c.trainingHistory=c.trainingHistory.slice(-100);const amount=Math.round((instructor?36:26)*mult*(ir04HasTalent('human_quickstudy')?1.15:1));gainSkill(skill,amount);ir04AwardXP(Math.max(2,Math.round(amount*.22)),`${skill} training`);c.mood=clamp(c.mood-1,0,100);addFeed(SKILLS[skill].icon,`${skill} training completed`,`You focused on ${skill}. ${instructor?'An instructor helped you progress faster.':'Independent practice improved your fundamentals.'}${mult<1?' Repeated recent sessions have diminishing returns.':''}`);persist();render();toast(`${skill} improved.`)}
function ir04UnlockTalent(id){const c=state.character;ir04EnsureState();const talents=IR_V04_RACIAL_TALENTS[c.race]||[];if(c.racialTalents.includes(id)){toast('That racial talent is already unlocked.');return}if(!talents.some(t=>t.id===id)){toast('That talent does not belong to your racial tree.');return}if(c.progression.talentPoints<1){toast('Gain a character level to earn racial talent points.');return}c.progression.talentPoints--;c.racialTalents.push(id);addFeed(RACES[c.race].icon,'Racial talent unlocked',`${talents.find(t=>t.id===id).name} is now active.`,'milestone');persist();render();toast('Racial talent unlocked.')}
function ir04TrainingPanel(){const c=state.character;const choices=[['Swordsmanship','⚔️','Sword and dagger techniques'],['Martial Arts','🥋','Unarmed combat and counters'],['Spear Arts','🔱','Reach and polearm technique'],['Axe Mastery','🪓','Heavy weapon control'],['Archery','🏹','Bow use and precision'],['Shield Handling','🛡️','Guarding and deflection'],['Elemental Magic','🔥','Offensive spellwork'],['Healing Magic','💚','Restorative magic'],['Tracking','🐾','Following prey and reading danger'],['Stealth','🌑','Sneaking and escape'],['Smithing','⚒️','Forging and repairing equipment'],['Leatherworking','🪡','Armor, hides, and field bandages'],['Alchemy','⚗️','Potions and reagents'],['Mining','⛏️','Ore and stone extraction'],['Herbalism','🌿','Useful plants and remedies'],['Fishing','🎣','Food from rivers and coasts'],['Trade','🪙','Buying, selling, and market knowledge'],['Negotiation','🤝','Contracts and peaceful outcomes'],['Monster Lore','📖','Threats and monster materials']];return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Focused training</h3><p>Choose the exact discipline you want to develop. Repeated practice in a short period gives diminishing returns.</p></div><span class="tag gold">FOCUS: ${esc(c.trainingFocus||'Swordsmanship')}</span></div><div class="ir04-training-grid">${choices.map(([name,icon,desc])=>`<div class="ir04-mini-card"><div class="row-icon">${icon}</div><div class="row-main"><strong>${esc(name)} · Lv. ${c.skills[name]?.level||1}</strong><p>${esc(desc)} · ${c.skills[name]?.xp||0}/100 XP</p></div><div class="row-side"><button class="button small" data-action="train-discipline" data-skill="${esc(name)}">Practice</button><button class="button small subtle" data-action="train-instructor" data-skill="${esc(name)}">Instructor · 8 ◈</button></div></div>`).join('')}</div><p class="ir-panel-copy">Self-practice costs 1 day and 13 energy. An instructor costs 8 coins as well and is available at guilds, work boards, forges, and libraries.</p></section>`}
function ir04ProgressionPanel(){const c=state.character;ir04EnsureState();const p=c.progression;const pct=Math.max(0,Math.min(100,p.xp/p.next*100));return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Character progression</h3><p>General experience grows separately from individual skills and attributes.</p></div><span class="tag gold">LEVEL ${p.level}</span></div><div class="ir04-xp"><div class="ir-bar-label"><strong>Next level</strong><b>${Math.floor(p.xp)} / ${p.next} XP</b></div><div class="ir-bar"><span class="player" style="width:${pct}%"></span></div></div><div class="ir-record-stats"><div><b>${p.attributePoints}</b><span>Attribute points</span></div><div><b>${p.talentPoints}</b><span>Racial talent points</span></div><div><b>${p.totalXp}</b><span>Total XP</span></div><div><b>${c.professionStats?.crafted||0}</b><span>Items crafted</span></div></div><div class="notice">Every level grants 2 attribute points; every even level grants a racial talent point. Skill mastery improves through relevant use and training.</div></section>`}
function ir04AttributePanel(){const c=state.character;ir04EnsureState();const stats=Object.keys(c.attrs||{});return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Attribute development</h3><p>Spend points earned from character levels. Each point improves one core attribute.</p></div><span class="tag gold">${c.progression.attributePoints} POINTS</span></div><div class="ir04-attribute-grid">${stats.map(stat=>`<div class="ir04-attribute"><div><strong>${esc(stat)}</strong><span>${c.attrs[stat]||1}</span></div><button class="button small" data-action="spend-attribute" data-stat="${esc(stat)}" ${c.progression.attributePoints<1||(c.attrs[stat]||1)>=40?'disabled':''}>+1</button></div>`).join('')}</div></section>`}
function ir04TalentPanel(){const c=state.character;ir04EnsureState();const list=IR_V04_RACIAL_TALENTS[c.race]||[];return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>${RACES[c.race].icon} ${esc(RACES[c.race].name)} talent tree</h3><p>Choose improvements that reflect the way your character is developing.</p></div><span class="tag purple">${c.progression.talentPoints} POINTS</span></div><div class="ir04-talent-grid">${list.map(t=>{const has=c.racialTalents.includes(t.id);return `<div class="ir04-mini-card"><div class="row-icon">${has?'✅':'✧'}</div><div class="row-main"><strong>${esc(t.name)}</strong><p>${esc(t.desc)}</p></div><div class="row-side"><button class="button small ${has?'':'primary'}" data-action="unlock-racial-talent" data-talent="${t.id}" ${has||c.progression.talentPoints<1?'disabled':''}>${has?'Unlocked':'Unlock · 1 pt'}</button></div></div>`}).join('')}</div></section>`}
function ir04CraftPanel(){const c=state.character;return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Crafting workbench</h3><p>Recipes consume materials. Professional stations charge modest service fees.</p></div><span class="tag">${site().name}</span></div><div class="ir04-recipe-grid">${Object.entries(IR_V04_RECIPES).map(([id,r])=>{const needs=Object.entries(r.needs).map(([k,n])=>`${ITEMS[k]?.name||k} ×${n}`).join(' · ');const skill=c.skills[r.skill]?.level||1;const stationOk=r.station==='field'||(r.station==='forge'&&(site().services||[]).some(x=>['forge','workshop','smithy'].includes(x)))||(r.station==='alchemy'&&(site().services||[]).some(x=>['library','alchemy','alchemist','lab'].includes(x)));return `<div class="ir04-recipe"><div class="recipe-title"><span>${r.icon}</span><strong>${esc(r.name)}</strong></div><p>${esc(r.desc)}</p><small>Requires ${esc(r.skill)} Lv. ${r.level} · ${esc(r.station==='field'?'Field kit':r.station==='forge'?'Forge / workshop':'Alchemy lab')}</small><small>Materials: ${esc(needs)}</small><button class="button small primary" data-action="craft-item" data-recipe="${id}" ${!ir04Needs(r.needs)||skill<r.level||!stationOk?'disabled':''}>Craft</button></div>`}).join('')}</div></section>`}
function ir04EconomyPanel(){const s=site(),c=state.character;const categories=['general','smithy','alchemist','hunter'];const active=state.world.shopCategory||'general';const items=(IR_V04_SHOPS[active]||IR_V04_SHOPS.general).filter(id=>IR_V04_ITEM_DATA[id]);const market=ir04MarketState();const can=ir04CanShop(active);return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Regional market</h3><p>Buying costs more than selling. Repeated sales lower offers; demand and shop specialty vary by region.</p></div><span class="tag gold">${coins(c.coin)}</span></div>${can?`<div class="ir04-shop-tabs">${categories.map(x=>`<button class="button small ${x===active?'primary':''}" data-action="market-category" data-category="${x}" ${!ir04CanShop(x)?'disabled':''}>${({general:'General goods',smithy:'Smithy',alchemist:'Alchemist',hunter:'Hunter'})[x]}</button>`).join('')}</div><div class="ir04-market-grid">${items.map(id=>{const d=IR_V04_ITEM_DATA[id],it=ITEMS[id],stock=market.stock[id]||0,buy=ir04ItemPrice(id,'buy'),sell=ir04ItemPrice(id,'sell');return `<div class="ir04-market-item"><div class="row-icon">${it?.icon||'📦'}</div><div class="row-main"><strong>${esc(it?.name||id)}</strong><p>${esc(it?.desc||'A useful trade good.')}</p><small>Stock ${stock} · Demand ×${(market.demand[d.category]||1).toFixed(2)}</small></div><div class="row-side"><b>Buy ${buy} ◈</b><button class="button small" data-action="market-buy" data-item="${id}" ${stock<1||c.coin<buy?'disabled':''}>Buy</button><b>Sell ${sell} ◈</b></div></div>`}).join('')}</div>`:`<div class="empty">No ${active} merchant is available here. The current location lacks the service needed for this shop.</div>`}<p class="ir-panel-copy">Market state is stored per settlement. Demand and recent trade persist through saving and loading; prices are bounded to prevent runaway inflation and arbitrage.</p></section>`}
function ir04GatherPanel(){const s=site();return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Gather resources</h3><p>Local geography affects which resources you can collect.</p></div><span class="tag">${esc(irBiomeProfileForSite(s).name)}</span></div><div class="actions-grid">${[['mining','⛏️','Mine ore and stone','Mining'],['woodcutting','🪵','Harvest timber','Woodcutting'],['herbalism','🌿','Gather plants and reagents','Herbalism'],['fishing','🎣','Catch food near water','Fishing']].map(([id,ico,title,sub])=>`<button class="action-card" data-action="gather-resource" data-method="${id}" ${!irBiomeGatheringAvailable(s,id)?'disabled':''}><span class="action-icon">${ico}</span><strong>${title}</strong><small>${sub} · 1–2 days and energy</small></button>`).join('')}</div></section>`}
function ir04WorldThreatCodex(){const ids=['goblin','wolf','bandit','guard','direwolf','ogre','troll','guardian','dragon'];return `<section class="panel panel-pad ir04-block" style="margin-top:15px"><div class="panel-heading"><div><h3>Threat scale & bestiary</h3><p>Creature strength is defined by threat tier, not copied from player level. Major threats are not random roadside encounters.</p></div><span class="tag warning">FIELD INTELLIGENCE</span></div><div class="ir04-threat-grid">${ids.map(id=>{const e=IR_ENEMIES[id];return `<div class="ir04-threat ${id==='dragon'?'ir04-national':''}"><div>${e.icon} <strong>${esc(e.name)}</strong></div><span class="tag ${e.threatRank>=5?'red':e.threatRank>=3?'gold':'blue'}">${esc(e.threatLabel||'Local threat')}</span><p>${e.hp.toLocaleString()} HP · ATK ${e.attack} · DEF ${e.defense}</p><small>${esc(e.threatDesc||e.desc)}</small></div>`}).join('')}</div><div class="notice">A dragon is a city- or nation-level threat with thousands of health and overwhelming strength. It is excluded from normal biome encounter pools and should be approached only through a major story, warning, and preparation chain.</div></section>`}
function ir04CustomInventory(){const c=state.character;ir04EnsureState();const entries=Object.entries(c.inventory||{}).filter(([id,n])=>n>0&&ITEMS[id]);const equipped=new Set([c.equipment?.weapon,c.equipment?.armor,c.equipment?.offhand].filter(Boolean));const gear=Object.entries(c.equipment||{}).map(([slot,id])=>({slot,id}));const current=site();return `${pageHead('Inventory, equipment & trade','Equip the right gear, maintain condition, transform gathered materials, and trade with specialized local merchants.')}<div class="grid two"><section class="panel panel-pad"><div class="panel-heading"><div><h3>Pack inventory</h3><p>${entries.reduce((sum,[id,n])=>sum+n,0)} items · ${ir04CarryWeight()} / ${ir04CarryCapacity()} weight carried.</p></div><span class="tag">${Object.keys(c.itemCondition).length} CONDITION RECORDS</span></div>${entries.length?entries.map(([id,n])=>{const it=ITEMS[id],equipable=!!(IR_WEAPON_DATA[id]||it.weaponDamage||it.armor),condition=c.itemCondition[id]??100;return `<div class="item-row"><div class="row-icon">${it.icon||'📦'}</div><div class="row-main"><strong>${esc(it.name)} <span class="tag">×${n}</span></strong><p>${esc(it.desc||'A useful item.')}</p><p>Base value ${IR_V04_ITEM_DATA[id]?.value??it.sell??1} ◈${IR_V04_ITEM_DATA[id]&&equipable?` · Condition ${condition}% · ${esc(c.itemQuality[id]||'Standard')}`:''}${equipped.has(id)?' · EQUIPPED':''}</p></div><div class="row-side">${equipable?`<button class="button small" data-action="equip-item" data-item="${id}">${equipped.has(id)?'Toggle gear':'Equip'}</button>`:''}${IR_V04_ITEM_DATA[id]&&!equipable?`<button class="button small" data-action="market-sell" data-item="${id}">Sell 1 · ${ir04ItemPrice(id,'sell')} ◈</button>`:''}</div></div>`}).join(''):'<div class="empty">Your pack is empty. Gather materials, hunt, craft, or visit a settlement market.</div>'}<div class="notice">Equipped items cannot be sold. Gear condition falls gradually during use; equipment is weakened at low durability but is never permanently destroyed.</div></section><section class="panel panel-pad"><div class="panel-heading"><div><h3>Equipment loadout</h3><p>Weapon skills improve damage with their matching equipment.</p></div><span class="tag gold">DEF ${irCurrentDefense()}</span></div><div class="ir04-gear-grid">${[['weapon','Weapon'],['armor','Armor'],['offhand','Off-hand']].map(([slot,title])=>{const id=c.equipment?.[slot],it=id?ITEMS[id]:null,cond=id?(c.itemCondition[id]??100):0;return `<div><span class="tiny-label">${title.toUpperCase()}</span><strong>${it?`${it.icon} ${esc(it.name)}`:'None equipped'}</strong><p>${id?`Condition ${cond}% · ${slot==='weapon'?`${irEquippedWeapon().damage} weapon damage`:slot==='offhand'?'Guard / defense bonus':'Armor protection'}`:'Choose an eligible item from your pack.'}</p>${id&&cond<100?`<button class="button small" data-action="repair-gear" data-slot="${slot}">Repair · ${Math.max(3,Math.ceil((IR_V04_ITEM_DATA[id]?.value||it.sell||10)*(100-cond)/180))} ◈</button>`:''}</div>`}).join('')}</div><div class="notice">Current focus: ${esc(c.trainingFocus)} · Weapon proficiency: ${(c.skills[IR_V04_WEAPON_SKILL[c.equipment?.weapon]||'Martial Arts']?.level||1)}. Shield Handling improves defense.</div><div class="section-label"><div><h3>Repair and service</h3><p>Professional repairs require a settlement service and coins.</p></div></div><button class="button" data-action="repair-gear" data-slot="weapon" ${!c.equipment?.weapon||(c.itemCondition[c.equipment.weapon]??100)>=100?'disabled':''}>Repair weapon</button> <button class="button" data-action="repair-gear" data-slot="armor" ${!c.equipment?.armor||(c.itemCondition[c.equipment.armor]??100)>=100?'disabled':''}>Repair armor</button> <button class="button" data-action="repair-gear" data-slot="offhand" ${!c.equipment?.offhand||(c.itemCondition[c.equipment.offhand]??100)>=100?'disabled':''}>Repair shield</button></section></div>${ir04EconomyPanel()}${ir04CraftPanel()}`}
function ir04AddMaterialsForEnemy(c,id){const e=IR_ENEMIES[id];if(!e)return;if(id==='wolf'||id==='direwolf'||id==='boar'){c.inventory.wolf_pelt=(c.inventory.wolf_pelt||0)+1;if(Math.random()<.5)c.inventory.leather=(c.inventory.leather||0)+1}if(id==='spider')c.inventory.spider_silk=(c.inventory.spider_silk||0)+1;if(id==='slime')c.inventory.slime_gel=(c.inventory.slime_gel||0)+1;if(['skeleton','wight'].includes(id))c.inventory.bone=(c.inventory.bone||0)+1}
function ir04RacialAction(){const b=state.combat,c=state.character,r=c.race,ab=IR_V04_RACIAL_ABILITIES[r];if(!b?.active||!ab)return;if(c.energy<ab.cost){toast(`You need ${ab.cost} energy for ${ab.name}.`);return}c.energy-=ab.cost;let log='';if(r==='human'){const dmg=Math.max(8,Math.round(9+(c.attrs.Intelligence||10)*.45+(c.skills.Combat?.level||1)));b.enemyHP=Math.max(0,b.enemyHP-dmg);log=`Rapid Adaptation finds an opening for ${dmg} damage.`;gainSkill(c.trainingFocus||'Swordsmanship',7)}else if(r==='dwarf'){b.guarding=true;const wid=c.equipment?.weapon;if(wid)c.itemCondition[wid]=Math.min(100,(c.itemCondition[wid]??100)+12);log='Masterwork Rhythm steadies your stance and restores 12 weapon condition.';gainSkill('Shield Handling',5)}else if(r==='elf'){let dmg=Math.round(14+(c.attrs.Wisdom||10)*.7+(c.skills['Elemental Magic']?.level||1)*2);if(ir04HasTalent('elf_arcanist'))dmg=Math.round(dmg*1.15);b.enemyHP=Math.max(0,b.enemyHP-dmg);log=`Elven Focus channels a precise arcane burst for ${dmg} damage.`;gainSkill('Elemental Magic',8)}else if(r==='beastkin'){const dmg=Math.round(8+(c.attrs.Perception||10)*.65+(c.skills.Tracking?.level||1));b.enemyHP=Math.max(0,b.enemyHP-dmg);log=`Hunter’s Instinct reveals a weak point and deals ${dmg} precise damage.`;gainSkill('Tracking',8)}else if(r==='orc'){const dmg=Math.round(15+(c.attrs.Strength||10)*.7+(c.skills.Swordsmanship?.level||1));b.enemyHP=Math.max(0,b.enemyHP-dmg);b.enemyAttack=Math.max(1,b.enemyAttack-3);log=`War Cry deals ${dmg} damage and shakes the enemy's resolve.`;gainSkill('Combat',9)}else if(r==='goblin'){const dmg=Math.round((7+(c.attrs.Agility||10)*.45+(c.skills.Stealth?.level||1))*(ir04HasTalent('goblin_dirty')?1.15:1));b.enemyHP=Math.max(0,b.enemyHP-dmg);if(Math.random()<.35)b.enemyStunned=1;log=`Dirty Trick deals ${dmg} damage${b.enemyStunned?' and interrupts the enemy':''}.`;gainSkill('Stealth',8)}else if(r==='demonkin'){let dmg=Math.round(22+(c.attrs.Wisdom||10)*.8+(c.skills['Elemental Magic']?.level||1)*2);if(ir04HasTalent('demonkin_bloodline'))dmg=Math.round(dmg*1.18);b.enemyHP=Math.max(0,b.enemyHP-dmg);log=`Bloodline Awakening releases ${dmg} shadow damage.`;gainSkill('Elemental Magic',10)}else{const healed=Math.min(c.maxHealth-c.health,Math.round(10*(ir04HasTalent('slimefolk_regen')?1.35:1)));c.health+=healed;b.guarding=true;log=`Fluid Shift restores ${healed} health and forms a defensive shell.`;gainSkill('Martial Arts',6)}irBattleLog(log);if(b.enemyHP<=0){irCombatEnd('victory',`${b.enemyName} was defeated by your racial ability.`);return}irEnemyTurn();persist();render()}
// Adjust enemy values so threat tiers are mechanically distinct rather than flattened by player level.
for(const [id,patch] of Object.entries(IR_V04_ENEMY_OVERRIDES)){if(IR_ENEMIES[id])Object.assign(IR_ENEMIES[id],patch);else IR_ENEMIES[id]=patch}
for(const [id,e] of Object.entries(IR_ENEMIES)){if(!e)continue;e.category=['wolf','spider','boar','direwolf'].includes(id)?'wildlife':(['goblin','slime'].includes(id)?'creature':(['thief','bandit','guard','cultist'].includes(id)?'humanoid':'monster'));}
// Keep national-scale threats out of ordinary procedural encounters.
for(const pool of Object.values(IR_BIOME_ENEMIES))if(!pool.includes('dragon')){/* intentional: dragons only appear through special high-threat content */}
const irV04MakeInitialBase=makeInitial;
makeInitial=function(name,raceId,bgId){const chosenStart=createStart;const s=irV04MakeInitialBase(name,raceId,bgId);createStart=chosenStart;ir04EnsureState(s);const c=s.character;c.progression={level:1,xp:0,next:120,attributePoints:0,talentPoints:0,totalXp:0};c.racialTalents=[];c.trainingHistory=[];c.trainingFocus=({human:'Swordsmanship',dwarf:'Smithing',elf:'Elemental Magic',beastkin:'Tracking',orc:'Swordsmanship',goblin:'Stealth',demonkin:'Elemental Magic',slimefolk:'Alchemy'}[c.race]||'Swordsmanship');c.itemCondition={};for(const id of Object.keys(c.inventory||{}))if(IR_V04_ITEM_DATA[id])c.itemCondition[id]=100;c.equipment=c.equipment||{};if(c.inventory.axe)c.equipment.weapon='axe';else if(c.inventory.staff)c.equipment.weapon='staff';else if(c.inventory.spear)c.equipment.weapon='spear';else if(c.inventory.iron_sword)c.equipment.weapon='iron_sword';else if(c.inventory.dagger)c.equipment.weapon='dagger';if(c.inventory.leather_armor)c.equipment.armor='leather_armor';if(c.inventory.shield)c.equipment.offhand='shield';const linked={dwarf_forgeward:['Smithing',2],elf_arcanist:['Elemental Magic',2],elf_groveward:['Herbalism',2],beastkin_tracker:['Tracking',2],orc_warveteran:['Swordsmanship',2],orc_duelist:['Martial Arts',2],goblin_scrapwright:['Smithing',1],goblin_alleyghost:['Stealth',2],demonkin_occultist:['Elemental Magic',2],slimefolk_laboratory:['Alchemy',2],slimefolk_collector:['Herbalism',1]};const link=linked[c.background];if(link&&c.skills[link[0]])c.skills[link[0]].level=Math.max(c.skills[link[0]].level,link[1]);s.version=4;return s};
const irV04NormalizeBase=normalizeSave;
