const irV04Style=document.createElement('style');irV04Style.textContent=`
.ir04-block{border-color:rgba(158,210,174,.22)}.ir04-attribute-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.ir04-attribute{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px;border:1px solid var(--line);background:#111d20;border-radius:10px}.ir04-attribute div{display:grid;gap:3px}.ir04-attribute strong{font-size:10px}.ir04-attribute span{font-size:17px;font-weight:800;color:var(--gold)}.ir04-training-grid,.ir04-talent-grid,.ir04-market-grid,.ir04-recipe-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.ir04-mini-card,.ir04-market-item,.ir04-recipe,.ir04-threat{min-width:0;border:1px solid var(--line);background:#111d20;border-radius:12px;padding:12px}.ir04-mini-card{display:flex;gap:9px;align-items:center}.ir04-mini-card .row-main{min-width:0}.ir04-mini-card .row-side{flex:0 0 auto}.ir04-mini-card .row-side button{margin:2px}.ir04-mini-card p,.ir04-recipe p,.ir04-threat small{color:var(--muted);font-size:10px;line-height:1.6;margin:4px 0}.ir04-mini-card small,.ir04-recipe small{display:block;color:var(--dim);font-size:9px;line-height:1.6;margin-top:4px}.ir04-talent-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.ir04-recipe-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ir04-recipe{display:flex;flex-direction:column;gap:6px}.ir04-recipe .button{align-self:flex-start;margin-top:7px}.recipe-title{display:flex;align-items:center;gap:8px}.recipe-title span{font-size:20px}.ir04-shop-tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.ir04-market-item{display:flex;align-items:center;gap:10px}.ir04-market-item .row-main{flex:1;min-width:0}.ir04-market-item small{font-size:9px;color:var(--dim)}.ir04-market-item .row-side{flex:0 0 90px}.ir04-gear-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.ir04-gear-grid>div{padding:12px;border:1px solid var(--line);background:#111d20;border-radius:11px;min-width:0}.ir04-gear-grid strong{display:block;font-size:12px;margin:7px 0}.ir04-gear-grid p{font-size:10px;line-height:1.65;color:var(--muted);min-height:42px}.ir04-threat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.ir04-threat>div{font-size:12px;display:flex;align-items:center;gap:5px;flex-wrap:wrap}.ir04-threat p{font-size:10px;color:var(--gold);margin:8px 0}.ir04-threat small{display:block}.ir04-national{border-color:#99554c;background:linear-gradient(140deg,#311e20,#171c20)}.ir04-xp{margin:12px 0 18px}.ir04-record-stats{margin:14px 0}.ir04-training-grid .button{white-space:nowrap}
@media(max-width:960px){.ir04-talent-grid,.ir04-threat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ir04-attribute-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ir04-training-grid{grid-template-columns:1fr}}
@media(max-width:680px){.ir04-talent-grid,.ir04-threat-grid,.ir04-recipe-grid,.ir04-market-grid,.ir04-gear-grid,.ir04-attribute-grid{grid-template-columns:1fr}.ir04-market-item{align-items:flex-start;flex-wrap:wrap}.ir04-market-item .row-side{flex:1 1 100%;flex-direction:row;align-items:center;justify-content:flex-start;gap:6px}.ir04-mini-card{align-items:flex-start;flex-wrap:wrap}.ir04-mini-card .row-side{display:flex;flex-direction:row;flex-wrap:wrap;width:100%}.ir04-shop-tabs .button{flex:1 1 auto}}
`;document.head.appendChild(irV04Style);
